"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["24508"],{44698(t){t.exports=JSON.parse("{\"id\":6934,\"title\":\"\u8868\u5355label\u5904\u7406\",\"description\":\"import { h } from 'vue';\\nimport { QuestionCircleOutlined } from '@ant-design/icons-vue';\\n\\n/**\\n * \u521B\u5EFA\u5E26\u6709\u53EF\u9009Tooltip\u7684\u8868\u5355\u6807\u7B7E\\n * @param label \u6807\u7B7E\u6587\u672C\\n * @param tips Tooltip\u63D0\u793A\u5185\u5BB9\uFF0C\u5982\u679C\u4E0D\u63D0\u4F9B\u5219\u4E0D\u663E\u793ATooltip\\n * @returns \u6E32\u67D3\u51FD\u6570\\n */\\nconst renderLabelWithTooltip = (label: string, tips?: string) => {\\n  // \u5982\u679C\u6CA1\u6709\u63D0\u4F9Btips\uFF0C\u5219\u53EA\u6E32\u67D3\u6807\u7B7E\u6587\u672C\\n  if (!tips) {\\n    return () => h('span', {}, label);\\n  }\\n  \\n  // \u5982\u679C\u63D0\u4F9B\u4E86tips\uFF0C\u5219\u6E32\u67D3\u5E26\u6709Tooltip\u7684\u6807\u7B7E\\n  return () => h('div', { style: { display: 'flex', alignItems: 'center' } }, [\\n    h('span', {}, label),\\n    h('a-tooltip', { title: tips }, {\\n      default: () => h(QuestionCircleOutlined, { \\n        style: { \\n          marginLeft: '4px',\\n          color: 'rgba(0, 0, 0, 0.45)',\\n          cursor: 'pointer',\\n          fontSize: '14px'\\n        } \\n      })\\n    })\\n  ]);\\n};\",\"owner\":\"tmx\",\"upvotes\":3,\"downvotes\":0,\"upvoteDifference\":3,\"updatedAt\":\"2026-04-13T20:38:42.869Z\"}")}}]);